import itertools

n = 15
fixed_edges = [(2,14), (6,13), (7,13), (10,13), (6,14)]

# Brute force bipartitions
found = False
for assignment in itertools.product([0, 1], repeat=n):
    ok = True
    for u, v in fixed_edges:
        if assignment[u] == assignment[v]:
            ok = False
            break
    if ok:
        print(f"Found bipartition: {assignment}")
        found = True
        # Build the graph: all cross edges
        edges = set(fixed_edges)
        for i in range(n):
            for j in range(i+1, n):
                if assignment[i] != assignment[j]:
                    edges.add((i, j))
        print(f"Total edges: {len(edges)}")
        print(f"Edges: {sorted(edges)}")
        break

if not found:
    print("No bipartition works")

n = 15
fixed_edges = [(2,14), (6,13), (7,13), (10,13), (6,14)]

# My solution: bipartition where left = {0,...,12}, right = {13,14}
left = set(range(13))
right = {13, 14}

edges = set()
for u in left:
    for v in right:
        edges.add((u, v) if u < v else (v, u))

# Check all fixed edges are present
for e in fixed_edges:
    assert e in edges, f"Missing fixed edge {e}"

print(f"Total edges: {len(edges)}")
print(f"Edges: {sorted(edges)}")

# Check no triangles
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            e1 = (i,j) in edges or (j,i) in edges
            e2 = (i,k) in edges or (k,i) in edges
            e3 = (j,k) in edges or (k,j) in edges
            if e1 and e2 and e3:
                print(f"Triangle found: {i},{j},{k}")
                break

print("No triangles found")

# Check maximality: for every non-edge, adding it creates a triangle
non_edges = []
for i in range(n):
    for j in range(i+1, n):
        if (i,j) not in edges:
            non_edges.append((i,j))

print(f"Number of non-edges: {len(non_edges)}")

for u, v in non_edges:
    # Check if adding (u,v) creates a triangle
    creates_triangle = False
    for w in range(n):
        if w == u or w == v:
            continue
        e_uw = (u,w) in edges or (w,u) in edges
        e_vw = (v,w) in edges or (w,v) in edges
        if e_uw and e_vw:
            creates_triangle = True
            break
    if not creates_triangle:
        print(f"Edge ({u},{v}) can be added without creating a triangle!")
        break
else:
    print("Graph is maximal triangle-free!")
